pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawAmount) public {
        // Restrict depositAmount to a reasonable range to avoid overflow in vm.deal
        depositAmount = bound(depositAmount, 1 ether, 100 ether);
        // withdrawAmount is only used to check that a prior partial withdraw doesn't break the invariant.
        // Bound it to be less than or equal to depositAmount so the partial withdraw can succeed.
        withdrawAmount = bound(withdrawAmount, 0, depositAmount);

        // Fund the contract by sending Ether from some EOA
        address donor = makeAddr("donor");
        vm.deal(donor, depositAmount);
        vm.prank(donor);
        (bool sent, ) = address(c).call{value: depositAmount}("");
        require(sent, "donation failed");

        // Owner performs an optional prior partial withdrawal (valid under onlyOwner)
        vm.prank(c.owner());
        c.withdraw(withdrawAmount);

        uint256 balanceBefore = address(c).balance;
        require(balanceBefore > 0, "balance must be positive for the test");

        // Owner calls withdrawAll
        vm.prank(c.owner());
        c.withdrawAll();

        // ASSERTION: After withdrawAll, the contract's ETH balance must be zero.
        // The correct implementation transfers the entire balance, the mutant leaves funds behind.
        assertEq(address(c).balance, 0, "withdrawAll should drain the contract");
    }
}

